def seed_footer(apps, schema_editor):
    page_model = apps.get_model("cms", "FooterAlertsPage")
    social_model = apps.get_model("cms", "FooterSocialLink")
    funder_model = apps.get_model("cms", "FooterFunder")
    database = schema_editor.connection.alias
    page, _ = page_model.objects.using(database).get_or_create(pk=1)
    social_model.objects.using(database).bulk_create(
        [
            social_model(page_id=page.pk, position=position, icon=icon, label=label, url=url)
            for position, icon, label, url in SOCIAL_LINKS
        ]
    )
    funder_model.objects.using(database).bulk_create(
        [
            funder_model(
                page_id=page.pk,
                position=position,
                name=name,
                logo_image=logo_image,
            )
            for position, name, logo_image in FUNDERS
        ]
    )


def unseed_footer(apps, schema_editor):
    database = schema_editor.connection.alias
    apps.get_model("cms", "FooterSocialLink").objects.using(database).all().delete()
    apps.get_model("cms", "FooterFunder").objects.using(database).all().delete()


